 * The structured result of parsing the codemod CLI arguments.
 */
export interface Flags {
  /** When true, apply transforms without writing changes to disk. */
  dry: boolean
  /** When true, list the available transforms instead of running them. */
  list: boolean
  /** The path to run transforms against. Defaults to `process.cwd()`. */
  path: string
  /** When true, print the transformed output. */
  print: boolean
  /** The name of the transform to run, if one was specified. */
  transform: string | undefined
}

/**
 * Parses an array of CLI argument strings into a structured {@link Flags}
 * object.
 *
 * The first positional (non-flag) argument is used as the `path`. Recognizes
 * `--dry`, `--dry-run` (an alias for `--dry`), `--list`, `--print`, and
 * `--transform <value>`.
 */
export function parseFlags(argv: string[]): Flags {
  const flags: Flags = {
    dry: false,
    list: false,
    path: process.cwd(),
    print: false,
    transform: undefined,
  }

  let pathSet = false

  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i]

    switch (arg) {
      case '--dry':
      case '--dry-run':
        flags.dry = true
        break
      case '--list':
        flags.list = true
        break
      case '--print':
        flags.print = true
        break
      case '--transform':
        flags.transform = argv[++i]
        break
      default:
        if (arg !== undefined && !arg.startsWith('-') && !pathSet) {
          flags.path = arg
          pathSet = true
        }
    }
  }

  return flags
}
