import type { Transform } from './types.js'

/**
 * The result of running a single {@link Transform}.
 */
export interface TransformRunResult {
  /** An error, if the transform threw while running. */
  error?: Error
  /** Paths of the source files that were modified by the transform. */
  filesChanged: string[]
  /** The name of the transform that produced this result. */
  name: string
  /** Optional human-readable notes about what the transform did. */
  notes?: string[]
}

/**
 * The aggregate result of running a set of transforms.
 */
export interface RunTransformsResult {
  /** True if any transform threw an error while running. */
  failed: boolean
  /** The per-transform results, in the order the transforms were supplied. */
  results: TransformRunResult[]
}

/**
 * Runs all supplied transforms in order against a ts-morph `Project`.
 *
 * Execution continues past any transform that throws, collecting a result for
 * every transform. The returned `failed` flag is true if any transform threw.
 */
export async function runTransforms({
  project,
  transforms,
}: {
  project: Project
  transforms: Transform[]
}): Promise<RunTransformsResult> {
  const results: TransformRunResult[] = []
  let failed = false

  for (const transform of transforms) {
    try {
      const result = await transform.apply({ project })
      results.push({
        name: transform.name,
        filesChanged: result.filesChanged,
        notes: result.notes,
      })
    } catch (error) {
      failed = true
      results.push({
        name: transform.name,
        error: error instanceof Error ? error : new Error(String(error)),
        filesChanged: [],
      })
    }
  }

  return { failed, results }
}
