import type { Transform } from '../types.js'

/**
 * Test helper that applies a {@link Transform} to a single source string in an
 * in-memory ts-morph `Project` and returns the resulting file's source text.
 *
 * @param source - The TypeScript source to run the transform against.
 * @param transform - The transform to apply.
 * @param filename - The name of the in-memory file. Defaults to `'input.ts'`.
 */
export async function runTransform({
  filename = 'input.ts',
  source,
  transform,
}: {
  filename?: string
  source: string
  transform: Transform
}): Promise<string> {
  const project = new Project({ useInMemoryFileSystem: true })
  const sourceFile = project.createSourceFile(filename, source, { overwrite: true })

  await transform.apply({ project })

  return sourceFile.getFullText()
}
