import { parseFlags } from './cli.parseFlags.js'
import { runTransforms } from './runner.js'
import { exampleNoop } from './transforms/example-noop/index.js'
import type { Transform } from './types.js'

/** All transforms available to the codemod CLI, keyed by name. */
const transforms: Record<string, Transform> = {
  [exampleNoop.name]: exampleNoop,
}

/**
 * Entry point for the `payload-codemod` CLI.
 */
export async function main(argv: string[]): Promise<void> {
  const flags = parseFlags(argv)

  if (flags.list) {
    for (const transform of Object.values(transforms)) {
      console.log(`${transform.name} - ${transform.description}`)
    }
    return
  }

  const selected = flags.transform ? transforms[flags.transform] : undefined

  if (!selected) {
    console.error(
      flags.transform
        ? `Unknown transform: ${flags.transform}`
        : 'No transform specified. Use --list to see available transforms.',
    )
    process.exitCode = 1
    return
  }

  const project = new Project({ tsConfigFilePath: undefined })
  project.addSourceFilesAtPaths(`${flags.path}/**/*.{ts,tsx}`)

  const { failed, results } = await runTransforms({ project, transforms: [selected] })

  for (const result of results) {
    if (result.error) {
      console.error(`${result.name} failed: ${result.error.message}`)
    } else {
      console.log(`${result.name}: ${result.filesChanged.length} file(s) changed`)
    }
  }

  if (flags.print) {
    for (const sourceFile of project.getSourceFiles()) {
      console.log(sourceFile.getFullText())
    }
  }

  if (!flags.dry && !failed) {
    await project.save()
  }

  if (failed) {
    process.exitCode = 1
  }
}
